    </ul>
}

@code {
    [PersistentState]
    public List<sv_bfe655ad468542aa8af22241189e1ac4.Services.NotificationItem>? PersistedNotifications { get; set; }

    private List<sv_bfe655ad468542aa8af22241189e1ac4.Services.NotificationItem> notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    protected override void OnInitialized()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender — skip re-fetching
            notifications = PersistedNotifications;
        }
        else
        {
            // First render (prerender): load initial data
            notifications = NotificationService.GetNotifications();
            PersistedNotifications = notifications;
        }

        _lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only starts after the page is interactive — never during prerender
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(5000, cancellationToken);

            // Simulate the service occasionally producing new notifications
            NotificationService.SimulateNewNotification();

            var newItems = NotificationService.GetNotificationsSince(_lastSeenId);
            if (newItems.Count > 0)
            {
                notifications.AddRange(newItems);
                _lastSeenId = newItems.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

